package app.space.notes.domain;
import org.junit.Test;
import static org.junit.Assert.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

public class ArchiveMergeTest {
 private static final String ID="00000000-0000-0000-0000-000000000001",OTHER="00000000-0000-0000-0000-000000000002",A=String.join("",Collections.nCopies(64,"a")),B=String.join("",Collections.nCopies(64,"b"));
 private ArchiveManifest manifest(boolean metadata){return new ArchiveManifest(2,A,Arrays.asList(new ArchiveManifest.Recording(ID,1,44,A,metadata?2:0,metadata?A:null,false)));}
 private Map<String,String> meta(boolean present){return present?Collections.singletonMap(ID,A):Collections.emptyMap();}
 private ArchiveMerge.Plan plan(boolean metadata,ArchiveMerge.Inventory inventory)throws Exception{return ArchiveMerge.preview(manifest(metadata),meta(metadata),Collections.emptyList(),Collections.emptyList(),inventory);}
 @Test public void newAudioAndMetadataAreOnlyPlannedNotWritten()throws Exception{ArchiveMerge.Plan plan=plan(true,id->null);assertEquals(1,plan.addedAudio);assertEquals(1,plan.addedMetadata);assertEquals(0,plan.conflictCopies);assertEquals(ID,plan.recordings.get(0).targetId);}
 @Test public void identicalRecordingAndTranscriptAreReused()throws Exception{ArchiveMerge.Plan plan=plan(true,id->new ArchiveMerge.Content(44,A,A));assertEquals(0,plan.addedAudio);assertEquals(1,plan.reusedAudio);assertEquals(0,plan.addedMetadata);assertEquals(ID,plan.recordings.get(0).targetId);}
 @Test public void missingIncomingMetadataDoesNotEraseCurrentTranscript()throws Exception{ArchiveMerge.Plan plan=plan(false,id->new ArchiveMerge.Content(44,A,B));assertEquals(1,plan.reusedAudio);assertEquals(0,plan.addedMetadata);assertEquals(0,plan.conflictCopies);}
 @Test public void missingCurrentMetadataCanBeAddedWithoutDuplicatingWave()throws Exception{ArchiveMerge.Plan plan=plan(true,id->new ArchiveMerge.Content(44,A,null));assertEquals(1,plan.reusedAudio);assertEquals(1,plan.addedMetadata);assertFalse(plan.recordings.get(0).addAudio);}
 @Test public void differentAudioOrTranscriptGetsAStableNonDestructiveCopy()throws Exception{for(boolean metadata:new boolean[]{false,true}){ArchiveMerge.Inventory inventory=id->id.equals(ID)?new ArchiveMerge.Content(44,metadata?A:B,metadata?B:null):null;ArchiveMerge.Plan first=plan(metadata,inventory),second=plan(metadata,inventory);assertEquals(1,first.conflictCopies);assertNotEquals(ID,first.recordings.get(0).targetId);assertEquals(first.recordings.get(0).targetId,second.recordings.get(0).targetId);assertEquals(1,first.addedAudio);}}
 @Test public void repeatedConflictImportReusesItsExistingCopy()throws Exception{ArchiveMerge.Plan first=plan(true,id->id.equals(ID)?new ArchiveMerge.Content(44,B,B):null);String target=first.recordings.get(0).targetId;ArchiveMerge.Plan again=plan(true,id->id.equals(ID)?new ArchiveMerge.Content(44,B,B):id.equals(target)?new ArchiveMerge.Content(44,A,A):null);assertEquals(target,again.recordings.get(0).targetId);assertEquals(0,again.addedAudio);assertEquals(1,again.reusedAudio);}
 @Test public void conflictRemapsPrimaryNoteAndAllLinksWithoutChangingOtherMetadata()throws Exception{
  Note primary=Note.create(1).withId(VoiceTranscripts.noteId(ID)).rich("Title","Words original",Arrays.asList(new Note.Mark("bold",0,5)),2).voiceSource(ID,3).voiceSource(OTHER,4).properties(3,Arrays.asList("work"),5).folder("Projects",6).background(15,7).reminder(999,8);
  Note linked=Note.create(1).edit("Other","Body",2).voiceSource(ID,3);ArchiveMerge.Plan plan=ArchiveMerge.preview(manifest(false),meta(false),Collections.emptyList(),Arrays.asList(primary,linked),id->id.equals(ID)?new ArchiveMerge.Content(44,B,null):null);String target=plan.recordings.get(0).targetId;Note copy=plan.notes.notes.get(0),other=plan.notes.notes.get(1);assertEquals(VoiceTranscripts.noteId(target),copy.id);assertEquals(Arrays.asList(target,OTHER),copy.voiceSources);assertEquals(primary.title,copy.title);assertEquals(primary.body,copy.body);assertEquals(primary.updatedAt,copy.updatedAt);assertEquals(primary.createdAt,copy.createdAt);assertEquals(primary.marks,copy.marks);assertEquals(primary.labels,copy.labels);assertEquals(primary.folder,copy.folder);assertEquals(primary.background,copy.background);assertEquals(primary.reminderAt,copy.reminderAt);assertEquals(linked.id,other.id);assertEquals(Arrays.asList(target),other.voiceSources);assertEquals(Arrays.asList(ID,OTHER),primary.voiceSources);
 }
 @Test public void conflictTargetsCannotStealAnotherIncomingSourceIdentity()throws Exception{String reserved=plan(false,id->id.equals(ID)?new ArchiveMerge.Content(44,B,null):null).recordings.get(0).targetId;ArchiveManifest manifest=new ArchiveManifest(2,A,Arrays.asList(new ArchiveManifest.Recording(ID,1,44,A,0,null,false),new ArchiveManifest.Recording(reserved,1,44,A,0,null,false)));ArchiveMerge.Plan plan=ArchiveMerge.preview(manifest,Collections.emptyMap(),Collections.emptyList(),Collections.emptyList(),id->id.equals(ID)?new ArchiveMerge.Content(44,B,null):null);Set<String> targets=new HashSet<>();for(ArchiveMerge.Target target:plan.recordings){assertTrue(targets.add(target.targetId));if(target.sourceId.equals(ID))assertNotEquals(reserved,target.targetId);}assertEquals(2,targets.size());}
 @Test public void metadataFactsMustExactlyCoverDeclaredTranscripts()throws Exception{assertThrows(IllegalArgumentException.class,()->ArchiveMerge.preview(manifest(true),Collections.emptyMap(),Collections.emptyList(),Collections.emptyList(),id->null));assertThrows(IllegalArgumentException.class,()->ArchiveMerge.preview(manifest(false),meta(true),Collections.emptyList(),Collections.emptyList(),id->null));Map<String,String> missing=new HashMap<>();missing.put(ID,null);assertThrows(IllegalArgumentException.class,()->ArchiveMerge.preview(manifest(true),missing,Collections.emptyList(),Collections.emptyList(),id->null));}
 @Test public void inventoryFailureAndExcessiveCollisionsAbortWithoutMutation()throws Exception{assertThrows(InterruptedIOException.class,()->plan(false,id->{throw new InterruptedIOException("cancel");}));AtomicInteger calls=new AtomicInteger();assertThrows(IOException.class,()->plan(false,id->{calls.incrementAndGet();return new ArchiveMerge.Content(44,B,null);}));assertTrue(calls.get()<=ArchiveManifest.MAX_RECORDINGS+2);}
}
